class Solution:
    def productExceptSelf(self, nums: list) -> list:
        n = len(nums)
        res = [1] * n
        prefix = 1
        for i in range(n):
            res[i] = prefix
            prefix *= nums[i]
        suffix = 1
        for i in range(n - 1, -1, -1):
            res[i] *= suffix
            suffix *= nums[i]
        return res

class Solution:
    def maxSubArray(self, nums: list) -> int:
        max_sum = nums[0]
        cur = nums[0]
        for x in nums[1:]:
            cur = max(x, cur + x)
            max_sum = max(max_sum, cur)
        return max_sum

class Solution:
    def longestPalindrome(self, s: str) -> str:
        if not s:
            return ''
        start, max_len = 0, 1
        for i in range(len(s)):
            # odd palindrome
            l, r = i, i
            while l >= 0 and r < len(s) and s[l] == s[r]:
                if r - l + 1 > max_len:
                    start = l
                    max_len = r - l + 1
                l -= 1
                r += 1
            # even palindrome
            l, r = i, i + 1
            while l >= 0 and r < len(s) and s[l] == s[r]:
                if r - l + 1 > max_len:
                    start = l
                    max_len = r - l + 1
                l -= 1
                r += 1
        return s[start:start + max_len]

class Solution:
    def myAtoi(self, s: str) -> int:
        s = s.lstrip()
        if not s:
            return 0
        sign = 1
        idx = 0
        if s[0] == '-':
            sign = -1
            idx = 1
        elif s[0] == '+':
            idx = 1
        res = 0
        while idx < len(s) and s[idx].isdigit():
            res = res * 10 + int(s[idx])
            idx += 1
        res = sign * res
        INT_MIN, INT_MAX = -2**31, 2**31 - 1
        if res < INT_MIN:
            return INT_MIN
        if res > INT_MAX:
            return INT_MAX
        return res

class Solution:
    def topKFrequent(self, nums: list, k: int) -> list:
        from collections import Counter
        counts = Counter(nums)
        return [item[0] for item in counts.most_common(k)]

class Solution:
    def subarraySum(self, nums: list, k: int) -> int:
        count = 0
        cur = 0
        prefix_sums = {0: 1}
        for x in nums:
            cur += x
            if cur - k in prefix_sums:
                count += prefix_sums[cur - k]
            prefix_sums[cur] = prefix_sums.get(cur, 0) + 1
        return count

class Solution:
    def twoSum(self, numbers: list, target: int) -> list:
        l, r = 0, len(numbers) - 1
        while l < r:
            s = numbers[l] + numbers[r]
            if s == target:
                return [l + 1, r + 1]
            elif s < target:
                l += 1
            else:
                r -= 1
        return []

class Solution:
    def sortColors(self, nums: list) -> list:
        low, mid, high = 0, 0, len(nums) - 1
        while mid <= high:
            if nums[mid] == 0:
                nums[low], nums[mid] = nums[mid], nums[low]
                low += 1
                mid += 1
            elif nums[mid] == 1:
                mid += 1
            else:
                nums[mid], nums[high] = nums[high], nums[mid]
                high -= 1
        return nums

class Solution:
    def lengthOfLongestSubstring(self, s: str) -> int:
        used = {}
        max_len = 0
        start = 0
        for i, ch in enumerate(s):
            if ch in used and start <= used[ch]:
                start = used[ch] + 1
            else:
                max_len = max(max_len, i - start + 1)
            used[ch] = i
        return max_len

class Solution:
    def search(self, nums: list, target: int) -> int:
        l, r = 0, len(nums) - 1
        while l <= r:
            mid = (l + r) // 2
            if nums[mid] == target:
                return mid
            if nums[l] <= nums[mid]:
                if nums[l] <= target < nums[mid]:
                    r = mid - 1
                else:
                    l = mid + 1
            else:
                if nums[mid] < target <= nums[r]:
                    l = mid + 1
                else:
                    r = mid - 1
        return -1
